<?php
require dirname(__DIR__).'/app/view.php';
$filters=[];foreach(['q','line','track','age','technology'] as $k) $filters[$k]=is_string($_GET[$k]??null)?trim($_GET[$k]):'';
$total=course_count($filters);$pages=max(1,(int)ceil($total/12));$page=max(1,min($pages,(int)($_GET['page']??1)));$items=courses($filters,12,($page-1)*12);
$techs=db()->query("SELECT DISTINCT technology FROM courses WHERE status='published' ORDER BY technology")->fetchAll(PDO::FETCH_COLUMN);
if(env('PAGES_BUILD')==='1'){$items=courses();$page=1;$pages=1;}
page_header('Programas','programas');breadcrumb('Programas');page_intro('CONSTRUYE TU PROPIO CAMINO','La curiosidad tiene<br><em>muchas formas.</em>','Explora programas y proyectos de robótica, programación y fabricación digital. Encuentra una propuesta para tu edad y tus intereses.');
?>
<section class="wrap catalog-section"><form class="filter-form" method="get" action="<?=url('programas.php')?>" role="search"><div class="search-field"><label for="q">¿Qué quieres aprender?</label><div><?=icon('search')?><input id="q" name="q" type="search" maxlength="150" placeholder="Robótica, Arduino, diseño 3D…" value="<?=e($filters['q'])?>"></div></div><div><label for="line">Línea</label><select name="line" id="line"><option value="">Todas las líneas</option><?php foreach(lines() as $key=>$label):?><option value="<?=$key?>" <?=$filters['line']===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div><label for="age">Edad</label><input name="age" id="age" type="number" min="3" max="99" placeholder="Ej. 10 años" value="<?=e($filters['age'])?>"></div><div><label for="technology">Tecnología</label><select name="technology" id="technology"><option value="">Todas</option><?php foreach($techs as $t):?><option value="<?=e($t)?>" <?=$filters['technology']===$t?'selected':''?>><?=e($t)?></option><?php endforeach;?></select></div><button class="button" type="submit">Buscar <?=icon('arrow')?></button><?php if($filters['track']):?><input type="hidden" name="track" value="<?=e($filters['track'])?>"><?php endif;?></form><div class="catalog-toolbar"><p><strong><?=$total?></strong> propuestas en catálogo</p><a href="<?=url('programas.php')?>">Limpiar filtros</a></div><?php if(!$items):?><div class="empty-state"><?=icon('search')?><h2>Probemos otro camino</h2><p>No encontramos propuestas con esos filtros. Puedes cambiar la edad o buscar por otra tecnología.</p><a class="button" href="<?=url('programas.php')?>">Ver todos los programas</a></div><?php else:?><div class="course-grid"><?php foreach($items as $c) course_card($c);?></div><nav class="pagination" aria-label="Páginas del catálogo"><?php for($n=1;$n<=$pages;$n++):$p=$filters;$p['page']=$n;?><a href="<?=url('programas.php?'.http_build_query(array_filter($p,fn($v)=>$v!=='')))?>" <?=$n===$page?'aria-current="page"':''?>><?=$n?></a><?php endfor;?></nav><?php endif;?><p class="catalog-note">La disponibilidad de grupos y proyectos se confirma al consultar. En programas para adultos, revisa los requisitos de ingreso.</p></section>
<?php page_footer(); ?>
